  const { Attributes } = await MODELO_PROGRAMA.build(EntityRepository).update(
    { programaId, duracionMinutos },
    {
      condition: { attr: 'programaId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PROGRAMA, MODELO_EMISORA } from '../../models/emisora-programa.model.mjs';

export async function buscarEmisoraRepository(emisoraId) {
  const { Item } = await MODELO_EMISORA.build(EntityRepository).get(
    { emisoraId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarEmisoraRepository(emisoraId, minimo) {
  const { Items = [] } = await MODELO_PROGRAMA.build(EntityRepository).query(
    { index: 'PorEmisora', partition: emisoraId },
    { filters: { Programa: { attr: 'duracionMinutos', gte: minimo } } }
  );
  return Items;
}

import { trasladarProgramaService } from './service.mjs';

export async function handler(event) {
  const programaId = Number(event.pathParameters.programaId);
  const { emisoraId } = JSON.parse(event.body);
  const resultado = await trasladarProgramaService(programaId, emisoraId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarProgramaRepository } from './repository.mjs';
import { buscarEmisoraRepository } from '../../emisoras/consultar/repository.mjs';

export async function trasladarProgramaService(programaId, emisoraId) {
  const emisora = await buscarEmisoraRepository(emisoraId);
  if (!emisora) throw new Error('Emisora no encontrado');
  return trasladarProgramaRepository(programaId, emisoraId);
}

